      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-token-billing\",\n  \"version\": \"0.8.1\",\n  \"description\": \"DSH 实时 token 计费插件：DeepSeek 官网人民币价直接计费（高峰/错峰按北京时间周一至周五窗口，周末空闲价）、价格自动跟随官网、可视化自定义模型价格、持久化历史账本、账户余额、CSV/JSON 导出、本地模型节省统计、订阅/免费/本地收费形式分类、Token 缓存命中统计、统计页仪表盘（KPI 概览 + 费用/Token 趋势折线图 + 按模型/Provider 占比环形图 + 月度预算预警）\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"check:parity\": \"node scripts/check-schema-parity.mjs\"\n  },\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./projection\": \"./lib/projection.js\",\n    \"./prices\": \"./lib/prices.js\",\n    \"./ledger\": \"./lib/ledger.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"slots\",\n        \"settingsScope\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"compatibility\": {\n      \"dsh\": \">=0.1.0-rc.8 <0.2.0\",\n      \"dshReleases\": {\n        \"0.1.0-rc.8\": \"compatible\",\n        \"0.1.1-rc.1\": \"compatible\",\n        \"0.1.1-rc.2\": \"compatible\",\n        \"0.1.2-alpha.1\": \"compatible\",\n        \"0.1.2-alpha.2\": \"compatible\",\n        \"0.1.2-alpha.3\": \"compatible\",\n        \"0.1.2-alpha.4\": \"compatible\",\n        \"0.1.2-alpha.5\": \"compatible\",\n        \"0.1.2-rc.1\": \"compatible\",\n        \"0.1.3-alpha.1\": \"compatible\",\n        \"0.1.3-alpha.2\": \"compatible\",\n        \"0.1.5-alpha.1\": \"compatible\",\n        \"0.1.5-alpha.2\": \"compatible\",\n        \"0.1.5-rc.1\": \"compatible\",\n        \"0.1.5-rc.2\": \"compatible\"\n      }\n    }\n  },\n  \"engines\": {\n    \"node\": \"^22.19.0 || >=24.0.0\",\n    \"dsh\": \">=0.1.0-rc.8 <0.2.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.1\",\n    \"@deepseek-ai/dsh-settings\": \">=0.1.0-rc.8 <0.2.0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.1\",\n    \"react\": \"^18.2.0\",\n    \"zod\": \">=4.0.0 <5.0.0\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\"\n  ],\n  \"license\": \"MIT\"\n}\n"
