    {
      "path": "lib/index.js",
      "content": "/**\n * dsh-token-billing — 宿主端插件入口（v0.2：官网实时价格 + DeepSeek 高峰/错峰计费）。\n *\n * 注册一个名为 `tokenBilling` 的会话投影：重放会话事件流，按模型价格表把\n * token 用量实时换算为费用（精确 usage 优先，流式期间用启发式估算并标记；\n * DeepSeek 高峰/错峰按官方时段自动切换计价）。\n *\n * 价格来源（`token-billing` settings 命名空间实时配置，改即重建、无需重启）：\n *  - builtin      仅内置表（近似价，用户可覆盖）\n *  - deepseek     抓取 DeepSeek 官方价格页（api-docs.deepseek.com），\n *                 解析平峰价 + 高峰/错峰价表与高峰时段，带 24h 缓存与后台自动刷新\n *  - custom-json  抓取用户自定义 JSON 价格端点（网关 / gist）\n * 合并优先级：用户「模型价格覆盖」> 官网抓取 > 内置表 > 未知模型默认价。\n *\n * 浏览器端「设置 → 插件 → Web UI 插件 → Token 计费」卡片可手动刷新价格，\n * 通过宿主路由 POST /token-billing/refresh（GET /token-billing/prices 查状态）。\n */\nimport { installSettingsSection, settingsNamespace } from '@deepseek-ai/dsh-settings'\nimport z from 'schemastery'\nimport { z as zod } from 'zod'\nimport {\n  createTokenBillingProjectionParts,\n  resolveBillingSpec,\n  applyFetchedPrices,\n  applyProviderPrices,\n  applyProviderPriceOverrides,\n  parseProviderUrlMap,\n  parseProviderPricesConfig,\n  parseProviderModes,\n  providerModeOf,\n  priceAt,\n  DEFAULT_FX_RATE,\n} from './projection.js'\nimport {\n  fetchDeepSeekPrices,\n  fetchJsonPrices,\n  loadProviderPrices,\n  listPiAiProviders,\n  loadPriceCache,\n  savePriceCache,\n  priceCachePath,\n  isCacheStale,\n  peakActive,\n} from './prices.js'\nimport { POLICY_PRICED_PROVIDER_IDS } from './coding-plans.js'\nimport {\n  ledgerPath,\n  loadLedger,\n  saveLedger,\n  mergeSteps,\n  computeStats,\n  dayKeyOf,\n  ledgerToCsv,\n  ledgerToJson,\n} from './ledger.js'\n\n/** 计费命名空间（浏览器端同样拼写此值）。 */\nexport const BILLING_SETTINGS_NAMESPACE = settingsNamespace('token-billing')\n\n/** 插件配置（settings 命名空间 token-billing 的 schema）。 */\nexport const Config = z.object({\n  enabled: z.boolean().default(true),\n  currency: z.string().default('¥'),\n  priceSource: z.string().default('deepseek'),\n  customPriceUrl: z.string().default(''),\n  providerPriceUrls: z.string().default('{}'),\n  providerPrices: z.string().default('{}'),\n  providerModes: z.string().default('{}'),\n  refreshHours: z.number().min(0.1).default(1),\n  fxEnabled: z.boolean().default(true),\n  fxRate: z.number().min(0.000001).default(7.2),\n  fallbackInput: z.number().min(0).default(2),\n  fallbackOutput: z.number().min(0).default(8),\n  fallbackCacheRead: z.number().min(0).default(0.5),\n  fallbackCacheWrite: z.number().min(0).default(2),\n  prices: z.string().default('{}'),\n  offPeakEnabled: z.boolean().default(true),\n  offPeakWindows: z.string().default('[[\"01:00\",\"04:00\"],[\"06:00\",\"10:00\"]]'),\n  offPeakRate: z.number().min(0).max(1).default(0.5),\n  offPeakModels: z.string().default('deepseek-*'),\n  offPeakTz: z.string().default('UTC'),\n  offPeakForce: z.boolean().default(false),\n  localProviders: z.string().default(''),\n  localCostPerM: z.number().min(0).default(0),\n  monthlyBudget: z.number().min(0).default(0),\n})\n\n/** 投影视图的 wire schema（host 校验后才发给浏览器）。 */\nconst costsRecord = zod.record(zod.string(), zod.number().nonnegative())\nconst viewSchema = zod.object({\n  currency: zod.string(),\n  billing: zod.object({\n    source: zod.string(),\n    peakBilling: zod.boolean(),\n    peakActive: zod.boolean(),\n    windows: zod.array(zod.tuple([zod.number(), zod.number()])),\n  }).strict(),\n  prices: zod.array(zod.object({\n    model: zod.string(),\n    input: zod.number().nonnegative(),\n    output: zod.number().nonnegative(),\n    cacheRead: zod.number().nonnegative(),\n    cacheWrite: zod.number().nonnegative(),\n    currency: zod.string(),\n  }).strict()),\n  providerPrices: zod.array(zod.object({\n    provider: zod.string(),\n    model: zod.string(),\n    input: zod.number().nonnegative(),\n    output: zod.number().nonnegative(),\n    cacheRead: zod.number().nonnegative(),\n    cacheWrite: zod.number().nonnegative(),\n    currency: zod.string(),\n  }).strict()),\n  totals: zod.object({\n    uncachedInputTokens: zod.number().int().nonnegative(),\n    outputTokens: zod.number().int().nonnegative(),\n    cacheReadTokens: zod.number().int().nonnegative(),\n    cacheWriteTokens: zod.number().int().nonnegative(),\n    costs: costsRecord,\n    calls: zod.number().int().nonnegative(),\n    estimatedSteps: zod.number().int().nonnegative(),\n    exactSteps: zod.number().int().nonnegative(),\n  }).strict(),\n  turn: zod.object({\n    number: zod.number().int().nonnegative(),\n    costs: costsRecord,\n    estimated: zod.boolean(),\n    steps: zod.number().int().nonnegative(),\n    estimatedSteps: zod.number().int().nonnegative(),\n  }).strict(),\n  active: zod.object({\n    turn: zod.number().int().nonnegative(),\n    step: zod.number().int().nonnegative(),\n    model: zod.string(),\n    provider: zod.string(),\n    uncachedInputTokens: zod.number().int().nonnegative(),\n    outputTokens: zod.number().int().nonnegative(),\n    cacheReadTokens: zod.number().int().nonnegative(),\n    cacheWriteTokens: zod.number().int().nonnegative(),\n    cost: zod.number().nonnegative(),\n    currency: zod.string(),\n    estimated: zod.boolean(),\n  }).strict().nullable(),\n  last: zod.object({\n    turn: zod.number().int().nonnegative(),\n    step: zod.number().int().nonnegative(),\n    model: zod.string(),\n    provider: zod.string(),\n    outputTokens: zod.number().int().nonnegative(),\n    cost: zod.number().nonnegative(),\n    currency: zod.string(),\n    estimated: zod.boolean(),\n  }).strict().nullable(),\n  perModel: zod.array(zod.object({\n    model: zod.string(),\n    calls: zod.number().int().nonnegative(),\n    uncachedInputTokens: zod.number().int().nonnegative(),\n    outputTokens: zod.number().int().nonnegative(),\n    cacheReadTokens: zod.number().int().nonnegative(),\n    cacheWriteTokens: zod.number().int().nonnegative(),\n    cost: zod.number().nonnegative(),\n    currency: zod.string(),\n    estimatedCalls: zod.number().int().nonnegative(),\n  }).strict()),\n  steps: zod.array(zod.object({\n    turn: zod.number().int().nonnegative(),\n    step: zod.number().int().nonnegative(),\n    model: zod.string(),\n    provider: zod.string(),\n    at: zod.number(),\n    uncachedInputTokens: zod.number().int().nonnegative(),\n    outputTokens: zod.number().int().nonnegative(),\n    cacheReadTokens: zod.number().int().nonnegative(),\n    cacheWriteTokens: zod.number().int().nonnegative(),\n    cost: zod.number().nonnegative(),\n    currency: zod.string(),\n    estimated: zod.boolean(),\n    mode: zod.string().optional(),\n  }).strict()),\n}).strict()\n\n/** 宿主端需要的服务。 */\nexport const inject = ['sessionProjections']\n\n/**\n * 注册 tokenBilling 投影 + 价格抓取管理（价格/配置变化时重建）。\n * @param ctx - host 插件上下文（sessionProjections + settings + webServer）。\n * @param config - 组合层配置（schema 默认值已由 loader 填充）。\n */\nexport function apply(ctx, config = {}) {\n  // 权威配置源：浏览器设置面就绪后换成 settings scope，否则用组合配置。\n  let current = () => config ?? {}\n  let disposeProjection\n  let fetchInFlight = false\n  /** 最近一次成功抓取（内存兜底；磁盘缓存同时保留）。 */\n  let lastFetched = null\n  /** 最近一次重建的计费规格（供路由读取当前生效单价）。 */\n  let currentSpec = null\n\n  const cachePath = priceCachePath()\n\n  /* ------------------------- 持久化账本（A1） ------------------------- */\n  const ledgerFile = ledgerPath()\n  let ledger = loadLedger(ledgerFile)\n  let ledgerTimer = null\n  const flushLedger = () => {\n    ledgerTimer = null\n    saveLedger(ledgerFile, ledger)\n  }\n  const scheduleLedgerFlush = () => {\n    if (ledgerTimer !== null) return\n    ledgerTimer = setTimeout(flushLedger, 1000)\n  }\n  /** 会话 id 提取（兼容 Session 对象 / 字符串）。 */\n  const sessionIdOf = (session) => {\n    if (session === null || session === undefined) return 'anon'\n    if (typeof session === 'string') return session\n    return String(session.id ?? session.sessionId ?? session.title ?? 'anon')\n  }\n  // 订阅投影变更：tokenBilling 每次结算 → 幂等合并进账本（1s 防抖落盘）\n  if (typeof ctx.sessionProjections?.onChanged === 'function') {\n    ctx.sessionProjections.onChanged((session, key, value) => {\n      if (key !== 'tokenBilling' || value === null || value === undefined) return\n      if (Array.isArray(value.steps) && value.steps.length > 0) {\n        mergeSteps(ledger, sessionIdOf(session), value.steps)\n        scheduleLedgerFlush()\n      }\n    })\n  }\n  if (typeof ctx.on === 'function') {\n    ctx.on('dispose', () => {\n      if (ledgerTimer !== null) { clearTimeout(ledgerTimer); ledgerTimer = null }\n      flushLedger()\n    })\n  }\n\n  /* ------------------------- 账户余额（A2） ------------------------- */\n  let balanceCache = { at: 0, data: null, error: null }\n  /** 余额抓取：复用 DEEPSEEK_API_KEY（env 或凭证），60s 缓存。 */\n  const fetchBalance = async () => {\n    const now = Date.now()\n    if (balanceCache.data !== null && now - balanceCache.at < 60_000) return { ok: true, ...balanceCache.data }\n    if (balanceCache.error !== null && now - balanceCache.at < 60_000) return { ok: false, error: balanceCache.error }\n    const key = process.env.DEEPSEEK_API_KEY\n      ?? (typeof ctx.credentials === 'object' ? ctx.credentials?.DEEPSEEK_API_KEY : undefined)\n      ?? ''\n    if (!key) {\n      balanceCache = { at: now, data: null, error: '未配置 DEEPSEEK_API_KEY' }\n      return { ok: false, error: balanceCache.error }\n    }\n    try {\n      const base = process.env.DEEPSEEK_BASE_URL ?? 'https://api.deepseek.com'\n      const res = await fetch(`${base}/user/balance`, {\n        headers: { authorization: `Bearer ${key}`, accept: 'application/json' },\n        signal: AbortSignal.timeout(5000),\n      })\n      if (!res.ok) throw new Error(`HTTP ${res.status}`)\n      const json = await res.json()\n      const data = {\n        balanceInfos: Array.isArray(json?.balance_infos) ? json.balance_infos : null,\n        isAvailable: json?.is_available === true,\n        raw: json,\n      }\n      balanceCache = { at: now, data, error: null }\n      return { ok: true, ...data }\n    } catch (err) {\n      balanceCache = { at: now, data: null, error: err.message ?? String(err) }\n      return { ok: false, error: balanceCache.error }\n    }\n  }\n\n  /** 本地 provider 名单（settings 逗号分隔字符串 → 数组）。 */\n  const localProvidersOf = () => {\n    const raw = current().localProviders\n    if (typeof raw !== 'string' || raw.trim() === '') return []\n    return raw.split(/[,，]/).map((s) => s.trim()).filter(Boolean)\n  }\n\n  /** 把 after 表中覆盖的模型合并到 base 表（after 优先，跳过 overrides）。 */\n  const mergeProviderFlat = (base, after, spec) => {\n    for (const [m, e] of Object.entries(after)) {\n      if (spec.overrides[m] !== undefined) continue\n      base[m] = e\n    }\n  }\n\n  /**\n   * 本机 DSH 实际配置的 provider 与模型清单（settings 命名空间 `llm-pi-ai` 的 providers 段）。\n   * **只读**：只读取，绝不写回 user settings。服务不可用或无该命名空间时返回 []。\n   */\n  const configuredProvidersOf = () => {\n    const svc = typeof ctx.get === 'function' ? ctx.get('settings') : undefined\n    if (!svc || typeof svc.describe !== 'function') return []\n    let descriptors = []\n    try { descriptors = svc.describe({ redactSecrets: true }) ?? [] } catch { return [] }\n    const descriptor = descriptors.find((d) => String(d?.ns) === 'llm-pi-ai')\n    const providers = descriptor?.value?.providers\n    if (providers === null || typeof providers !== 'object') return []\n    const out = []\n    for (const [id, entry] of Object.entries(providers)) {\n      if (entry === null || typeof entry !== 'object') continue\n      const models = Array.isArray(entry.models)\n        ? entry.models.map((m) => (typeof m === 'string' ? m : m?.id)).filter((s) => typeof s === 'string' && s !== '')\n        : []\n      out.push({\n        provider: String(id),\n        displayName: typeof entry.displayName === 'string' && entry.displayName !== '' ? entry.displayName : String(id),\n        api: typeof entry.api === 'string' ? entry.api : '',\n        baseURL: typeof entry.baseURL === 'string' ? entry.baseURL : '',\n        models,\n      })\n    }\n    out.sort((a, b) => (a.provider < b.provider ? -1 : a.provider > b.provider ? 1 : 0))\n    return out\n  }\n\n  /** 账本里实际出现过的 provider（收窄需要装配价目的路由集合）。 */\n  const providersInLedger = () => {\n    const set = new Set()\n    for (const s of ledger?.steps ?? []) {\n      if (typeof s.provider === 'string' && s.provider !== '' && s.provider !== '(无)') set.add(s.provider)\n    }\n    return set\n  }\n\n  /**\n   * 为「本机实际存在的路由」装配 provider 价表（重建投影前调用）。\n   *\n   * 取数三层（disk → asar → builtin，见 lib/prices.js loadProviderPrices），\n   * 实际命中层如实写入 spec.providerSources，不谎报来源（空表也不登记）。\n   *\n   * 只装配**相关** provider（本机已配置 ∪ 账本用过 ∪ 配了价格 URL）——否则 catalog 里\n   * 几十个无关 provider 的上千条价目会全进会话投影，让每次视图推送携带大量无用数据。\n   *\n   * 优先级：显式 provider 价目（override）> URL 抓取（custom-json）> 三层 catalog 价。\n   */\n  const attachProviderPrices = (spec) => {\n    if (!spec.providerPrices) spec.providerPrices = {}\n    if (!spec.providerSources) spec.providerSources = {}\n    let urlMap = {}\n    try { urlMap = parseProviderUrlMap(current().providerPriceUrls) } catch { urlMap = {} }\n    const wanted = new Set([\n      ...configuredProvidersOf().map((p) => p.provider),\n      ...providersInLedger(),\n      ...Object.keys(urlMap),\n      ...Object.keys(spec.providerPrices), // 缓存里已抓到的 provider\n    ])\n    // 1) 三层取数（磁盘 → asar → 随包内置），来源如实标注\n    //\n    // 但**官方价格政策链权威定价的 provider 除外**（t7 评审 F1，队长授权方案 1）：\n    // pi-ai catalog 的 `deepseek.json` 是 pre-2026-08-17 的静态快照（USD、无峰谷、\n    // cacheWrite 记 0、无时间维度），一旦种进 `providerPrices['deepseek']`，就会按 priceAt 的\n    // 「provider 表优先」语义**盖住** `PRICE_POLICY_TIMELINE`（空闲输出低约一半、cacheWrite=0、\n    // 不参与峰谷、历史回看被追溯改写）。故这里跳过它，让 DeepSeek 官方模型一律走政策链。\n    //\n    // 护栏 (a) 以 **provider id** 为键跳过：`loadProviderPrices(name)` 只读 `<name>.json`，\n    //   因此只有恰好叫这些名字的路由会命中，不会误伤其它 provider 的 catalog 价\n    //   （例如 opencode-go/deepseek-v4-flash 的 0.22 原样保留）。\n    // 护栏 (b) 跳过时**不建桶、不登记 providerSources**，让 /token-billing/providers 对该路由\n    //   如实显示 `none`（不谎报来源）。\n    // 逃生口保留：用户显式配置（下面第 2 步的 URL 抓取、第 3 步的 providerPrices）不受影响。\n    for (const provider of wanted) {\n      if (POLICY_PRICED_PROVIDER_IDS.includes(provider)) continue\n      const { source, models } = loadProviderPrices(provider)\n      if (source !== 'none') applyProviderPrices(spec, provider, models, source)\n    }\n    // 2) 缓存中的 URL 抓取结果覆盖 catalog 价（source='custom-json'）\n    const cached = lastFetched ?? loadPriceCache(cachePath)\n    if (cached !== null && cached.providerFlat && typeof cached.providerFlat === 'object') {\n      for (const [provider, flat] of Object.entries(cached.providerFlat)) {\n        if (typeof flat !== 'object' || flat === null) continue\n        const bucket = (spec.providerPrices[provider] ??= {})\n        const before = Object.keys(bucket).length\n        mergeProviderFlat(bucket, flat, spec)\n        if (Object.keys(bucket).length > before) spec.providerSources[provider] = 'custom-json'\n      }\n    }\n    // 3) 用户在设置卡显式钉死的 provider 价目（最高，source='override'）\n    let explicit = {}\n    try { explicit = parseProviderPricesConfig(current().providerPrices) } catch { explicit = {} }\n    applyProviderPriceOverrides(spec, explicit)\n  }\n\n  /** 当前配置 → 计费规格（合并缓存/内存中的抓取价格）。 */\n  const buildSpec = () => {\n    const spec = resolveBillingSpec(current())\n    const cached = lastFetched ?? loadPriceCache(cachePath)\n    applyFetchedPrices(spec, cached, Date.now())\n    attachProviderPrices(spec)\n    return spec\n  }\n\n  const registerProjection = (spec) => {\n    if (disposeProjection !== undefined) {\n      disposeProjection()\n      disposeProjection = undefined\n    }\n    if (spec.enabled === false) return\n    const parts = createTokenBillingProjectionParts(spec)\n    // 兼容双核心（0.1.0-rc.8 读顶层 schema/view；0.1.1-rc.1+ 只读 wire 块——\n    // 缺 wire 时注册表视单元为 host-only：快照跳过、帧不推送、onChanged 不通知）。\n    // stateSchema 校验的是持久化检查点里的单元状态（纯 JSON 契约），不是视图。\n    disposeProjection = ctx.sessionProjections.register({\n      key: parts.key,\n      stateSchema: zod.json(),\n      init: parts.init,\n      apply: parts.apply,\n      view: parts.view,\n      wire: { viewSchema, view: parts.view },\n      stateVersion: parts.stateVersion,\n    })\n  }\n\n  const rebuild = () => {\n    try {\n      const spec = buildSpec()\n      currentSpec = spec\n      registerProjection(spec)\n    } catch (err) {\n      console.warn(`[token-billing] 配置无效，沿用未注册状态：${err.message}`)\n    }\n  }\n\n  /**\n   * 周期跟随官网：每分钟检查一次。\n   *  - 高峰/错峰生效时刻（effectiveAt）到达时，立即重建投影（峰谷价自动切换）；\n   *  - 价格表缓存过期（refreshHours）或来源变更时，后台重抓官网。\n   * 价格表跟随官网变化、峰谷价按当前时刻生效，均无需重启。\n   */\n  let lastPeakActive = null\n  let lastSource = null\n  const tick = () => {\n    const cfg = current()\n    const cached = lastFetched ?? loadPriceCache(cachePath)\n    if (cached !== null) {\n      const activeNow = peakActive(cached, cfg.offPeakForce === true, Date.now())\n      if (activeNow !== lastPeakActive || cached.source !== lastSource) {\n        lastPeakActive = activeNow\n        lastSource = cached.source\n        rebuild()\n      }\n    }\n    refreshPrices(false).catch(() => {})\n  }\n  const timer = setInterval(tick, 60_000)\n  if (typeof ctx.on === 'function') {\n    ctx.on('dispose', () => clearInterval(timer))\n  }\n\n  /** 抓取一次价格并重建投影。force=true 忽略缓存过期。 */\n  const refreshPrices = async (force = false) => {\n    if (fetchInFlight) return { ok: false, error: '正在抓取中，请稍候' }\n    const cfg = current()\n    let providerUrls = {}\n    try { providerUrls = parseProviderUrlMap(cfg.providerPriceUrls) } catch { providerUrls = {} }\n    const cached = loadPriceCache(cachePath)\n    const urlsEqual = cached !== null && cached.providerUrls !== undefined\n      && JSON.stringify(cached.providerUrls) === JSON.stringify(providerUrls)\n    const stale = cached === null\n      || isCacheStale(cached, cfg.refreshHours)\n      || cached.source !== cfg.priceSource\n      || (cfg.priceSource === 'custom-json' && cached.url !== cfg.customPriceUrl)\n      || (Object.keys(providerUrls).length > 0 && !urlsEqual)\n    if (!force && !stale) return { ...statusWithEffective(cached, Date.now()), ok: true, cached: true }\n    fetchInFlight = true\n    try {\n      let fetched = null\n      let isBuiltin = false\n      if (cfg.priceSource === 'deepseek') {\n        fetched = await fetchDeepSeekPrices()\n      } else if (cfg.priceSource === 'custom-json') {\n        fetched = await fetchJsonPrices(cfg.customPriceUrl)\n      } else {\n        isBuiltin = true\n      }\n      // 按 provider 抓自定义 URL（各自独立容错，不阻塞整体）；折算后存入缓存 providerFlat\n      const providerFlat = {}\n      if (Object.keys(providerUrls).length > 0) {\n        const spec = resolveBillingSpec(cfg)\n        for (const [provider, url] of Object.entries(providerUrls)) {\n          try {\n            const pf = await fetchJsonPrices(url)\n            applyFetchedPrices(spec, pf, Date.now(), provider)\n            if (spec.providerPrices[provider]) providerFlat[provider] = spec.providerPrices[provider]\n          } catch (err) {\n            console.warn(`[token-billing] provider「${provider}」价格抓取失败：${err.message}`)\n          }\n        }\n      }\n      if (isBuiltin && Object.keys(providerUrls).length === 0) {\n        // builtin 且无 provider URL：无抓取记录，但可展示内置表当前生效价\n        return { ok: true, source: 'builtin', fetchedAt: null, flatModels: 0, peak: null, fx: fxStatus(), effective: effectiveFrom(Date.now()) }\n      }\n      const record = {\n        ...(fetched ?? {}),\n        source: cfg.priceSource,\n        url: cfg.customPriceUrl,\n        providerUrls,\n        providerFlat,\n        fetchedAt: Date.now(),\n      }\n      savePriceCache(cachePath, record)\n      lastFetched = record\n      rebuild()\n      return { ...statusWithEffective(record, Date.now()), ok: true }\n    } catch (err) {\n      console.warn(`[token-billing] 价格抓取失败：${err.message}`)\n      return { ok: false, error: err.message }\n    } finally {\n      fetchInFlight = false\n    }\n  }\n\n  /** 当前折算配置（外币→目标货币）。 */\n  const fxStatus = () => {\n    const cfg = current()\n    return {\n      enabled: cfg.fxEnabled !== false,\n      rate: cfg.fxRate,\n      target: cfg.currency,\n    }\n  }\n\n  const statusOf = (record) => ({\n    source: record.source ?? 'builtin',\n    fetchedAt: record.fetchedAt ?? null,\n    currency: record.currency ?? null,\n    flatModels: Object.keys(record.flat ?? {}).length,\n    peak: record.peak === null ? null : {\n      models: Object.keys(record.peak.models ?? {}).length,\n      windows: record.peak.windows ?? [],\n      effectiveAt: record.peak.effectiveAt ?? null,\n    },\n  })\n\n  /** 附带当前折算配置的价格状态。 */\n  const statusWithFx = (record) => ({\n    ...(record === null ? { ok: false, error: '尚无价格缓存' } : { ok: true, ...statusOf(record) }),\n    fx: fxStatus(),\n  })\n\n  /** 所有模型当前生效单价表（含高峰/错峰，按 now 计价）——builtin 无抓取记录时也能展示。 */\n  const effectiveFrom = (now = Date.now()) => {\n    if (currentSpec === null) return {}\n    const effective = {}\n    for (const model of Object.keys(currentSpec.prices)) {\n      const p = priceAt('', model, currentSpec, now)\n      effective[model] = {\n        input: p.input,\n        output: p.output,\n        cacheRead: p.cacheRead,\n        cacheWrite: p.cacheWrite,\n        currency: p.currency,\n      }\n    }\n    return effective\n  }\n\n  /** 账本里实际用过（有计费 step）的 provider 集合；空则回退显示全部。 */\n  const usedProvidersOf = () => {\n    const set = new Set()\n    for (const s of ledger.steps ?? []) {\n      if (s.provider && s.provider !== '' && s.provider !== '(无)') set.add(s.provider)\n    }\n    return set\n  }\n\n  /** 按 provider 的当前生效单价表（已折算，按 now 计价），供状态页展示 provider 模型价格。 */\n  const providerEffectiveFrom = (now = Date.now()) => {\n    if (currentSpec === null) return {}\n    const used = usedProvidersOf()\n    const out = {}\n    for (const [provider, bucket] of Object.entries(currentSpec.providerPrices ?? {})) {\n      if (used.size > 0 && !used.has(provider)) continue\n      const prov = {}\n      for (const [model, entry] of Object.entries(bucket)) {\n        prov[model] = {\n          input: entry.input,\n          output: entry.output,\n          cacheRead: entry.cacheRead,\n          cacheWrite: entry.cacheWrite,\n          currency: entry.currency ?? currentSpec.currency,\n        }\n      }\n      out[provider] = prov\n    }\n    return out\n  }\n\n  /**\n   * 按 provider 的价目来源明细（如实标注实际命中的取数层）：\n   * disk / asar / builtin（三层取数）、custom-json（URL 抓取）、override（用户在设置卡钉死）。\n   * 空桶不登记来源，避免谎报。\n   */\n  const providerSourcesOf = () => {\n    if (currentSpec === null) return {}\n    const out = {}\n    const sources = currentSpec.providerSources ?? {}\n    for (const [provider, bucket] of Object.entries(currentSpec.providerPrices ?? {})) {\n      if (bucket === null || typeof bucket !== 'object' || Object.keys(bucket).length === 0) continue\n      out[provider] = sources[provider] ?? 'unknown'\n    }\n    return out\n  }\n\n  /** 每个 provider 当前的收费形式（exact + 声明顺序 glob 解析后的生效值）。 */\n  const providerModesOf = () => {\n    if (currentSpec === null) return {}\n    const out = {}\n    for (const [provider, bucket] of Object.entries(currentSpec.providerPrices ?? {})) {\n      if (bucket === null || typeof bucket !== 'object' || Object.keys(bucket).length === 0) continue\n      out[provider] = providerModeOf(currentSpec, provider)\n    }\n    return out\n  }\n\n  /** 附带「当前生效单价表」（含高峰/错峰，按当前时刻计价），供设置卡「状态」页实时展示。 */\n  const statusWithEffective = (record, now = Date.now()) => {\n    const base = statusWithFx(record)\n    if (record === null || currentSpec === null) {\n      return { ...base, effective: {}, providerEffective: {}, providerSources: {}, providerModes: {} }\n    }\n    return {\n      ...base,\n      effective: effectiveFrom(now),\n      providerEffective: providerEffectiveFrom(now),\n      providerSources: providerSourcesOf(),\n      providerModes: providerModesOf(),\n    }\n  }\n\n  // 浏览器端手动刷新/查询价格的路由（仅 web profile 存在 webServer）。\n  if (typeof ctx.inject === 'function') {\n    ctx.inject(['webServer'], (host) => {\n      /** 读取 POST JSON 请求体（有界）。 */\n      const readJsonBody = (req) => new Promise((resolve, reject) => {\n        const chunks = []\n        let size = 0\n        req.on('data', (chunk) => {\n          size += chunk.length\n          if (size > 256 * 1024) {\n            reject(new Error('body too large'))\n            req.destroy()\n            return\n          }\n          chunks.push(chunk)\n        })\n        req.on('end', () => {\n          try {\n            resolve(chunks.length === 0 ? {} : JSON.parse(Buffer.concat(chunks).toString('utf8')))\n          } catch {\n            reject(new Error('invalid JSON body'))\n          }\n        })\n        req.on('error', reject)\n      })\n\n      host.webServer.register({\n        name: 'token-billing-refresh',\n        kind: 'exact',\n        path: '/token-billing/refresh',\n        handler: async (req, res) => {\n          if (req.method !== 'POST') {\n            res.writeHead(405, { 'content-type': 'application/json' })\n            res.end(JSON.stringify({ ok: false, error: 'method not allowed' }))\n            return\n          }\n          try {\n            const result = await refreshPrices(true)\n            res.writeHead(200, { 'content-type': 'application/json' })\n            res.end(JSON.stringify(result))\n          } catch (err) {\n            res.writeHead(500, { 'content-type': 'application/json' })\n            res.end(JSON.stringify({ ok: false, error: err.message }))\n          }\n        },\n      })\n      host.webServer.register({\n        name: 'token-billing-prices',\n        kind: 'exact',\n        path: '/token-billing/prices',\n        handler: (req, res) => {\n          const record = lastFetched ?? loadPriceCache(cachePath)\n          res.writeHead(200, { 'content-type': 'application/json' })\n          res.end(JSON.stringify(statusWithEffective(record, Date.now())))\n        },\n      })\n\n      /**\n       * 按路由价目总览（**只读**）：本机配置的 provider + 其模型、各自当前生效单价、\n       * 价目来源（disk / asar / builtin / custom-json / override）与收费形式，\n       * 以及用户在设置卡里已显式钉死的 provider 价目。\n       *\n       * 走 HTTP 路由而不是 projection view：这些是**宿主级全局**的配置/只读状态，\n       * 与单会话计费无关；塞进会话投影 wire 会让全局数据随每次会话重建重复传输。\n       */\n      host.webServer.register({\n        name: 'token-billing-providers',\n        kind: 'exact',\n        path: '/token-billing/providers',\n        handler: (req, res) => {\n          const cfg = current()\n          let urls = {}\n          try { urls = parseProviderUrlMap(cfg.providerPriceUrls) } catch { urls = {} }\n          let explicit = {}\n          try { explicit = parseProviderPricesConfig(cfg.providerPrices) } catch { explicit = {} }\n          let modes = []\n          try { modes = parseProviderModes(cfg.providerModes) } catch { modes = [] }\n          const spec = currentSpec\n          // 本机已配置的 provider ∪ 账本里真实出现过的 provider（后者便于为历史路由补价）\n          const routes = configuredProvidersOf()\n          const seen = new Set(routes.map((r) => r.provider))\n          for (const provider of providersInLedger()) {\n            if (seen.has(provider)) continue\n            seen.add(provider)\n            routes.push({ provider, displayName: provider, api: '', baseURL: '', models: [] })\n          }\n          routes.sort((a, b) => (a.provider < b.provider ? -1 : a.provider > b.provider ? 1 : 0))\n          const payload = routes.map((entry) => {\n            const bucket = spec?.providerPrices?.[entry.provider] ?? {}\n            const prices = {}\n            for (const [model, e] of Object.entries(bucket)) {\n              prices[model] = {\n                input: e.input,\n                output: e.output,\n                cacheRead: e.cacheRead,\n                cacheWrite: e.cacheWrite,\n                currency: e.currency ?? spec.currency,\n              }\n            }\n            return {\n              provider: entry.provider,\n              displayName: entry.displayName,\n              api: entry.api,\n              baseURL: entry.baseURL,\n              models: entry.models,\n              prices,\n              source: spec?.providerSources?.[entry.provider] ?? 'none',\n              mode: spec === null ? 'usage' : providerModeOf(spec, entry.provider),\n              priceUrl: urls[entry.provider] ?? '',\n            }\n          })\n          res.writeHead(200, { 'content-type': 'application/json' })\n          res.end(JSON.stringify({\n            ok: true,\n            currency: cfg.currency || '¥',\n            fx: { enabled: cfg.fxEnabled !== false, rate: Number(cfg.fxRate) || DEFAULT_FX_RATE },\n            providerModes: ['usage', 'subscription', 'free', 'local'],\n            routes: payload,\n            explicitPrices: explicit,\n            explicitModes: Object.fromEntries(modes.map((m) => [m.pattern, m.mode])),\n            // 三层可取数的 provider 名单（内置表 ∪ 磁盘 ∪ asar），供编辑器挑选模型\n            catalogProviders: listPiAiProviders(),\n          }))\n        },\n      })\n\n      /** 读取本命名空间的配置（走宿主 settings 服务，避开家族/官方白名单）。 */\n      const readConfig = () => {\n        const svc = typeof ctx.get === 'function' ? ctx.get('settings') : undefined\n        if (svc && typeof svc.describe === 'function') {\n          const descriptor = svc.describe({ redactSecrets: true })\n            .find((d) => String(d.ns) === 'token-billing')\n          if (descriptor !== undefined) {\n            return {\n              ok: true,\n              value: descriptor.value,\n              base: descriptor.base ?? {},\n              user: descriptor.user ?? {},\n              revision: descriptor.revision,\n              writable: svc.writable !== false,\n            }\n          }\n        }\n        // 兜底：组合层配置（无 settings 服务时）\n        return { ok: true, value: current(), base: {}, user: {}, revision: 0, writable: true }\n      }\n\n      host.webServer.register({\n        name: 'token-billing-config',\n        kind: 'exact',\n        path: '/token-billing/config',\n        handler: (req, res) => {\n          res.writeHead(200, { 'content-type': 'application/json' })\n          res.end(JSON.stringify(readConfig()))\n        },\n      })\n\n      host.webServer.register({\n        name: 'token-billing-config-save',\n        kind: 'exact',\n        path: '/token-billing/config/save',\n        handler: async (req, res) => {\n          if (req.method !== 'POST') {\n            res.writeHead(405, { 'content-type': 'application/json' })\n            res.end(JSON.stringify({ ok: false, error: 'method not allowed' }))\n            return\n          }\n          try {\n            const body = await readJsonBody(req)\n            if (body === null || typeof body !== 'object' || typeof body.section !== 'object' || body.section === null) {\n              res.writeHead(400, { 'content-type': 'application/json' })\n              res.end(JSON.stringify({ ok: false, error: 'section 必须是对象' }))\n              return\n            }\n            const svc = typeof ctx.get === 'function' ? ctx.get('settings') : undefined\n            if (!svc || typeof svc.replace !== 'function') {\n              res.writeHead(500, { 'content-type': 'application/json' })\n              res.end(JSON.stringify({ ok: false, error: 'settings 服务不可用' }))\n              return\n            }\n            await svc.replace(BILLING_SETTINGS_NAMESPACE, body.section, body.expectedRevision)\n            const after = readConfig()\n            res.writeHead(200, { 'content-type': 'application/json' })\n            res.end(JSON.stringify({ ok: true, revision: after.revision }))\n          } catch (err) {\n            res.writeHead(400, { 'content-type': 'application/json' })\n            res.end(JSON.stringify({ ok: false, error: err.message ?? String(err) }))\n          }\n        },\n      })\n\n      /** 历史统计（今日/本月/累计/按模型/按天/节省/收费形式/缓存命中）。 */\n      host.webServer.register({\n        name: 'token-billing-stats',\n        kind: 'exact',\n        path: '/token-billing/stats',\n        handler: (req, res) => {\n          const cfg = current()\n          let providerModes = []\n          try { providerModes = parseProviderModes(cfg.providerModes) } catch { providerModes = [] }\n          const stats = computeStats(ledger, {\n            now: Date.now(),\n            tz: cfg.offPeakTz || 'Asia/Shanghai',\n            localProviders: localProvidersOf(),\n            localCostPerM: Number.isFinite(cfg.localCostPerM) ? cfg.localCostPerM : 0,\n            currency: cfg.currency || '¥',\n            providerModes,\n          })\n          // 图表辅助数据：近 14 天本地时区时间轴 + 月度预算（供统计页折线图/预算环使用）\n          const tzNow = Date.now()\n          const tzKey = cfg.offPeakTz || 'Asia/Shanghai'\n          const seriesLabels = []\n          for (let i = 13; i >= 0; i -= 1) seriesLabels.push(dayKeyOf(tzNow - i * 86_400_000, tzKey))\n          stats.seriesLabels = seriesLabels\n          stats.budget = {\n            monthly: Number.isFinite(cfg.monthlyBudget) && cfg.monthlyBudget > 0 ? cfg.monthlyBudget : 0,\n            currency: cfg.currency || '¥',\n          }\n          res.writeHead(200, { 'content-type': 'application/json' })\n          res.end(JSON.stringify({ ok: true, stats }))\n        },\n      })\n\n      /** 导出账本（?format=csv|json）。 */\n      host.webServer.register({\n        name: 'token-billing-export',\n        kind: 'exact',\n        path: '/token-billing/export',\n        handler: (req, res) => {\n          const url = new URL(req.url ?? '/', 'http://localhost')\n          const format = url.searchParams.get('format') === 'csv' ? 'csv' : 'json'\n          if (format === 'csv') {\n            res.writeHead(200, { 'content-type': 'text/csv; charset=utf-8', 'content-disposition': 'attachment; filename=\"token-billing-ledger.csv\"' })\n            res.end('\\uFEFF' + ledgerToCsv(ledger))\n          } else {\n            res.writeHead(200, { 'content-type': 'application/json', 'content-disposition': 'attachment; filename=\"token-billing-ledger.json\"' })\n            res.end(ledgerToJson(ledger))\n          }\n        },\n      })\n\n      /** 账户余额（只读，60s 缓存）。 */\n      host.webServer.register({\n        name: 'token-billing-balance',\n        kind: 'exact',\n        path: '/token-billing/balance',\n        handler: async (req, res) => {\n          const result = await fetchBalance()\n          res.writeHead(200, { 'content-type': 'application/json' })\n          res.end(JSON.stringify(result))\n        },\n      })\n    })\n  }\n\n  installSettingsSection(ctx, BILLING_SETTINGS_NAMESPACE, Config, config ?? {}, {\n    setSource: (source) => { current = source },\n    onChange: () => {\n      rebuild()\n      // 价格来源或刷新参数变化时，异步补一次抓取（后台进行，不阻塞）。\n      refreshPrices(false).catch(() => {})\n    },\n  })\n  rebuild()\n  refreshPrices(false).catch(() => {})\n}\n\nexport { createTokenBillingProjectionParts, resolveBillingSpec, applyFetchedPrices } from './projection.js'\nexport { parseDeepSeekPricingHtml, fetchDeepSeekPrices, fetchJsonPrices } from './prices.js'\n"
